{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Rapamycin, the closest retrieved analog, crosses the BBB after systemic administration in several species, with measurable rapamycin in CSF and brain tissue or inhibition of brain mTORC1 signaling.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Dictyostatin shows good brain penetration in mice with a brain AUC0.5–16h of 6245 nM·h after systemic administration, supporting meaningful CNS access for a macrocyclic analog.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Temsirolimus, a close analog, showed detectable CSF concentrations in only 1 of 9 patients, indicating poor CNS penetration and arguing against assuming all close analogs behave like rapamycin.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The closest analog, rapamycin, has direct multi-species evidence of brain and CSF penetration after systemic dosing, and several other macrocyclic analogs show measurable brain exposure. A close analog, temsirolimus, shows poor CSF penetration, creating mixed evidence, but the strongest and most direct positive record from the closest analog supports a pass prediction.",
  "evidence_gaps": [
    "Closest analogs are split: rapamycin supports CNS access while temsirolimus does not.",
    "Temsirolimus negative evidence is CSF-based and may not fully reflect brain tissue exposure.",
    "Several supporting positive analogs have low Morgan similarity (<0.2), limiting transferability.",
    "Clarithromycin evidence comes from meningitis models with disrupted BBB and was not used as primary support."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

